const body = $input.first().json;

// Extract summary
const summary = body.summary || {};
const failed = summary.failed || 0;
const passed = summary.passed || 0;
const skipped = summary.skipped || 0;
const total = summary.total || 0;
const duration = body.duration_seconds || 0;
const runId = body.run_id || 'unknown';

// Collect failed tests for the email
const allTests = body.all_tests || [];
const failedTests = allTests.filter(t => t.status === 'fail');

// Build HTML failure details
let failureRows = '';
for (const t of failedTests) {
  failureRows += `<tr style="background:#fff0f0">
    <td style="padding:6px 12px;border:1px solid #fcc">${t.group}</td>
    <td style="padding:6px 12px;border:1px solid #fcc;font-weight:bold">${t.test}</td>
    <td style="padding:6px 12px;border:1px solid #fcc;color:#c00">${t.message}</td>
    <td style="padding:6px 12px;border:1px solid #fcc">${t.duration_ms}ms</td>
  </tr>`;
}

// Group summary rows
const groups = body.groups || [];
let groupRows = '';
for (const g of groups) {
  const statusColor = g.failed > 0 ? '#c00' : '#080';
  groupRows += `<tr>
    <td style="padding:6px 12px;border:1px solid #ddd">${g.name}</td>
    <td style="padding:6px 12px;border:1px solid #ddd;color:#080">${g.passed}</td>
    <td style="padding:6px 12px;border:1px solid #ddd;color:${statusColor}">${g.failed}</td>
    <td style="padding:6px 12px;border:1px solid #ddd;color:#888">${g.skipped || 0}</td>
  </tr>`;
}

const overallColor = failed === 0 ? '#080' : '#c00';
const overallStatus = failed === 0 ? '✅ ALL PASSING' : `❌ ${failed} FAILED`;

const htmlBody = `<!DOCTYPE html>
<html>
<head><style>
  body { font-family: Arial, sans-serif; color: #333; max-width: 900px; margin: 0 auto; padding: 20px; }
  h1 { color: ${overallColor}; }
  h2 { color: #555; margin-top: 30px; }
  table { border-collapse: collapse; width: 100%; margin-bottom: 20px; }
  th { background: #f5f5f5; padding: 8px 12px; border: 1px solid #ddd; text-align: left; }
  .badge { display: inline-block; padding: 4px 10px; border-radius: 4px; font-weight: bold; }
  .pass { background: #d4edda; color: #155724; }
  .fail { background: #f8d7da; color: #721c24; }
  .meta { color: #888; font-size: 0.9em; margin-bottom: 20px; }
</style></head>
<body>
  <h1>DabbahWala E2E Test Suite — ${overallStatus}</h1>
  <p class="meta">
    Run ID: ${runId}<br/>
    Date: ${body.started_at || new Date().toISOString()}<br/>
    Duration: ${duration}s
  </p>

  <h2>Summary</h2>
  <table>
    <tr><th>Total</th><th>Passed</th><th>Failed</th><th>Skipped</th></tr>
    <tr>
      <td style="padding:8px 12px;border:1px solid #ddd;font-size:1.2em;font-weight:bold">${total}</td>
      <td style="padding:8px 12px;border:1px solid #ddd;color:#080;font-size:1.2em;font-weight:bold">${passed}</td>
      <td style="padding:8px 12px;border:1px solid #ddd;color:${overallColor};font-size:1.2em;font-weight:bold">${failed}</td>
      <td style="padding:8px 12px;border:1px solid #ddd;color:#888;font-size:1.2em">${skipped}</td>
    </tr>
  </table>

  <h2>By Group</h2>
  <table>
    <tr><th>Group</th><th>Passed</th><th>Failed</th><th>Skipped</th></tr>
    ${groupRows}
  </table>

  ${failedTests.length > 0 ? `
  <h2 style="color:#c00">Failed Tests (${failedTests.length})</h2>
  <table>
    <tr><th>Group</th><th>Test</th><th>Error</th><th>Duration</th></tr>
    ${failureRows}
  </table>` : '<p style="color:#080;font-size:1.1em">✓ All tests passed — system healthy.</p>'}
</body>
</html>`;

return [{
  json: {
    run_id: runId,
    failed,
    passed,
    total,
    duration,
    overall_status: overallStatus,
    has_failures: failed > 0,
    html_body: htmlBody,
    subject: `DabbahWala E2E Test Suite — ${overallStatus} (${passed}/${total} passed, ${duration}s)`,
    to: 'vivek@dabbahwala.com',
  }
}];
